import pyomo.environ as pyo

DATA = {
    "source": 0,
    "sink": 6,
    "nodes": [0, 1, 2, 3, 4, 5, 6],
    # arc (i, j) -> capacity in TB/hr.  0 denotes "no link" and is omitted.
    "capacity": {
        (0, 1): 17, (0, 2): 3, (0, 3): 20, (0, 4): 11, (0, 5): 11, (0, 6): 3,
        (1, 0): 11, (1, 2): 12, (1, 3): 18, (1, 4): 5, (1, 5): 6, (1, 6): 4,
        (2, 0): 7, (2, 1): 2, (2, 3): 15, (2, 4): 13, (2, 5): 20, (2, 6): 18,
        (3, 0): 7, (3, 1): 4, (3, 2): 2, (3, 4): 2, (3, 5): 15, (3, 6): 3,
        (4, 0): 19, (4, 1): 12, (4, 2): 16, (4, 3): 4, (4, 5): 19, (4, 6): 4,
        (5, 0): 13, (5, 1): 20, (5, 2): 10, (5, 3): 14, (5, 4): 15, (5, 6): 1,
        (6, 0): 3, (6, 1): 3, (6, 2): 6, (6, 3): 20, (6, 4): 9, (6, 5): 10,
    },
}


def build_model(data=None):
    d = data or DATA

    source = d["source"]
    sink = d["sink"]
    nodes = list(d["nodes"])
    capacity = {a: u for a, u in d["capacity"].items() if u > 0}
    arcs = list(capacity.keys())

    # arcs leaving / entering each node (for conservation)
    out_arcs = {n: [a for a in arcs if a[0] == n] for n in nodes}
    in_arcs = {n: [a for a in arcs if a[1] == n] for n in nodes}

    model = pyo.ConcreteModel()

    model.N = pyo.Set(initialize=nodes, ordered=True)
    model.A = pyo.Set(initialize=arcs, dimen=2, ordered=True)
    # intermediate nodes need conservation (exclude source and sink)
    model.Interior = pyo.Set(
        initialize=[n for n in nodes if n != source and n != sink], ordered=True
    )

    # f[i,j]: terabytes per hour on arc (i,j), bounded by that arc's capacity
    def flow_bounds(m, i, j):
        return (0, capacity[(i, j)])

    model.f = pyo.Var(model.A, domain=pyo.NonNegativeReals, bounds=flow_bounds)

    # Flow conservation: outflow - inflow == 0 at every interior node
    def conservation_rule(m, n):
        return (
            sum(m.f[a] for a in out_arcs[n])
            - sum(m.f[a] for a in in_arcs[n])
            == 0
        )

    model.conservation = pyo.Constraint(model.Interior, rule=conservation_rule)

    # Objective: maximise total flow leaving the source (equals flow into sink)
    def obj_rule(m):
        return sum(m.f[a] for a in out_arcs[source])

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    return model


